package dev.zomboid.clans;
import java.util.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.server.level.*;import me.danialisntcool.factionfriction.data.FactionManager;import net.neoforged.neoforge.event.entity.EntityMobGriefingEvent;
public class Checks {
 static int count;static void ok(boolean b,String message){count++;if(!b)throw new AssertionError(message);}
 public static class Tag{public Map<String,Object> data=new HashMap<>();public String getString(String k){return String.valueOf(data.getOrDefault(k,""));}public boolean getBoolean(String k){return Boolean.TRUE.equals(data.get(k));}public void putBoolean(String k,boolean v){data.put(k,v);}public void remove(String k){data.remove(k);}}
 public static class Join{public Entity entity;public boolean disk,canceled;public Join(Entity e){entity=e;}public Level getLevel(){return entity.world;}public Entity getEntity(){return entity;}public boolean isCanceled(){return canceled;}public void setCanceled(boolean c){canceled=c;}public boolean loadedFromDisk(){return disk;}}
 public record Conversion(Entity entity,Entity outcome){public Entity getEntity(){return entity;}public Entity getOutcome(){return outcome;}}
 public static class PlayerZombie extends Mob implements net.smileycorp.hordes.common.entities.PlayerZombie{PlayerZombie(Level w){super(w,"hordes:zombie_player");}}
 static void join(Join e){Pve.join(e);}static Mob mob(Level w,String id){return new Mob(w,id);}
 public static void main(String[] a){boolean old=a.length>0&&a[0].equals("old");ServerLevel w=new ServerLevel();w.server=new net.minecraft.server.MinecraftServer();FactionManager m=FactionManager.instance;m.claims.put("overworld",new HashSet<>(Set.of(new ChunkPos(0,0).toLong(),new ChunkPos(-1,-1).toLong())));
  if(old){Join cow=new Join(mob(w,"minecraft:cow"));join(cow);ok(!cow.canceled,"native .14 lets animals spawn in claims");UUID id=UUID.randomUUID();((Map)R.get(Pve.class,"waves")).put(id,new Pve.Wave(id));Join wave=new Join(mob(w,"minecraft:zombie"));wave.entity.tag.data.put("FactionPveWave",id.toString());join(wave);ok(!wave.canceled,"native .14 lets active wave spawn in claims");EntityMobGriefingEvent grief=new EntityMobGriefingEvent(mob(w,"minecraft:zombie"));R.call(R.type("me.danialisntcool.factionfriction.event.protection.ProtectionEventHandler"),"onMobGriefing",grief);ok(!grief.can,"native .14 prevents zombie grief in claims");System.out.println("Native .14 reproduced: "+count);return;}
  for(String id:new String[]{"minecraft:zombie","minecraft:husk","minecraft:drowned","mutantszombies:screamer","mutants_l4d2:witch","minecraft:skeleton","minecraft:creeper","minecraft:cow","minecraft:villager","tnpc:bandit"}){Join e=new Join(mob(w,id));join(e);ok(e.canceled,"new creature blocked "+id);ok(!e.entity.tag.getBoolean(SpawnClaims15.SEEN),"rejected mob not marked existing "+id);}
  for(String reason:new String[]{"NATURAL","SPAWNER","SPAWN_EGG","BREEDING","COMMAND","STRUCTURE","EVENT","MOD_ADD_FRESH_ENTITY"}){Join e=new Join(mob(w,"minecraft:zombie"));e.entity.tag.data.put("reason",reason);join(e);ok(e.canceled,"all insertion reasons "+reason);}
  Join saved=new Join(mob(w,"minecraft:zombie"));saved.disk=true;join(saved);ok(!saved.canceled&&saved.entity.tag.getBoolean(SpawnClaims15.SEEN),"disk-loaded mob preserved");saved.disk=false;join(saved);ok(!saved.canceled,"existing mob reattached preserved");
  Mob visitor=mob(w,"minecraft:cow");visitor.x=32;Join visiting=new Join(visitor);join(visiting);ok(!visiting.canceled,"outside spawn allowed");visitor.x=0;join(visiting);ok(!visiting.canceled,"existing visitor can reattach inside");
  Join negative=new Join(mob(w,"minecraft:zombie"));negative.entity.x=-1;negative.entity.z=-1;join(negative);ok(negative.canceled,"negative chunk lookup");ok(!SpawnClaims15.spot(w,-1,-1),"negative wave spot");ok(SpawnClaims15.spot(w,-17,-1),"negative outside boundary");
  Join turret=new Join(mob(w,"tacz_turrets:turret"));join(turret);ok(!turret.canceled,"manufactured turret remains placeable");
  for(String id:new String[]{"minecraft:player","corpse:corpse","remains:body","minecraft:item","tacz:bullet","minecraft:boat"}){Join e=new Join(new Entity(w,id));join(e);ok(!e.canceled,"non-creature unaffected "+id);}
  Join infected=new Join(new PlayerZombie(w));join(infected);ok(!infected.canceled,"infected player replacement and inventory preserved");
  UUID waveId=UUID.randomUUID();((Map)R.get(Pve.class,"waves")).put(waveId,new Pve.Wave(waveId));Join wave=new Join(mob(w,"minecraft:zombie"));wave.entity.tag.data.put("FactionPveWave",waveId.toString());join(wave);ok(wave.canceled,"active wave has no claim bypass");Join outsideWave=new Join(mob(w,"minecraft:zombie"));outsideWave.entity.x=32;outsideWave.entity.tag.data.put("FactionPveWave",waveId.toString());join(outsideWave);ok(!outsideWave.canceled,"active wave allowed outside");Join stale=new Join(mob(w,"minecraft:zombie"));stale.disk=true;stale.entity.x=32;stale.entity.tag.data.put("FactionPveWave",UUID.randomUUID().toString());join(stale);ok(stale.canceled,"native orphan wave cleanup retained");
  ServerLevel nether=new ServerLevel();nether.server=w.server;nether.dim="nether";Join other=new Join(mob(nether,"minecraft:zombie"));join(other);ok(!other.canceled,"same coordinates disabled dimension allowed");m.enabled.add("nether");m.claims.put("nether",Set.of(new ChunkPos(0,0).toLong()));Join netherClaim=new Join(mob(nether,"minecraft:zombie"));join(netherClaim);ok(netherClaim.canceled,"claims in enabled other dimension enforced");
  m.claims.get("overworld").remove(new ChunkPos(0,0).toLong());Join unclaimed=new Join(mob(w,"minecraft:zombie"));join(unclaimed);ok(!unclaimed.canceled,"unclaim takes effect immediately");m.claims.get("overworld").add(new ChunkPos(0,0).toLong());ok(!SpawnClaims15.spot(w,0,0)&&SpawnClaims15.spot(w,32,0),"wave surface search excludes claims");
  w.client=true;Join client=new Join(mob(w,"minecraft:zombie"));join(client);ok(!client.canceled&&!client.entity.tag.getBoolean(SpawnClaims15.SEEN),"client untouched");w.client=false;Join canceled=new Join(mob(w,"minecraft:cow"));canceled.canceled=true;join(canceled);ok(canceled.canceled&&!canceled.entity.tag.getBoolean(SpawnClaims15.SEEN),"other mod cancellation preserved");
  for(String id:new String[]{"minecraft:zombie","minecraft:husk","minecraft:drowned","mutantszombies:screamer","mutants_l4d2:witch"}){EntityMobGriefingEvent e=new EntityMobGriefingEvent(mob(w,id));R.call(R.type("me.danialisntcool.factionfriction.event.protection.ProtectionEventHandler"),"onMobGriefing",e);ok(e.can,"native claim veto removed for "+id);e.can=false;R.call(R.type("me.danialisntcool.factionfriction.event.protection.ProtectionEventHandler"),"onMobGriefing",e);ok(!e.can,"other grief veto not overridden "+id);}
  EntityMobGriefingEvent creeper=new EntityMobGriefingEvent(mob(w,"minecraft:creeper"));R.call(R.type("me.danialisntcool.factionfriction.event.protection.ProtectionEventHandler"),"onMobGriefing",creeper);ok(!creeper.can,"native non-zombie protection retained");
  Mob original=mob(w,"minecraft:zombie");original.tag.putBoolean(SpawnClaims15.SEEN,true);Mob drowned=mob(w,"minecraft:drowned");Join converted=new Join(drowned);join(converted);ok(converted.canceled,"replacement initially filtered");SpawnClaims15.converted(new Conversion(original,drowned));ok(drowned.added&&drowned.tag.getBoolean(SpawnClaims15.SEEN),"existing zombie conversion retained");
  Mob untracked=mob(w,"minecraft:drowned");SpawnClaims15.converted(new Conversion(original,untracked));ok(!untracked.added,"conversion event cannot exempt an unrelated spawn");
  Mob unknown=mob(w,"minecraft:zombie"),fresh=mob(w,"minecraft:drowned");join(new Join(fresh));SpawnClaims15.converted(new Conversion(unknown,fresh));ok(!fresh.added,"unadmitted source cannot create an exception");
  Mob refused=mob(w,"minecraft:drowned");join(new Join(refused));w.rejectAddition=true;SpawnClaims15.converted(new Conversion(original,refused));ok(!refused.added&&!refused.tag.getBoolean(SpawnClaims15.SEEN),"other mod rejection retained without marking");w.rejectAddition=false;
  Mob removed=mob(w,"minecraft:drowned");join(new Join(removed));removed.removed=true;SpawnClaims15.converted(new Conversion(original,removed));ok(!removed.added,"removed replacement never resurrected");
  System.out.println("Native .15 and production policy checks: "+count);
 }
}
